CREATE   PROCEDURE dbo.sp_Admin_Assignment_Create
(
    @ActorID INT,
    @NguoiDungID INT,
    @RapID INT,
    @NgayBatDau DATE,
    @NgayKetThuc DATE = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    -- R3B: current account, actor eligibility, then every required permission.
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N'Hoạt động')
        THROW 50300, N'Tài khoản không tồn tại hoặc đã bị khóa.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID
                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN ('ADMIN'))
        THROW 50301, N'Vai trò không được phép thực hiện thao tác này.', 1;
    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, 'PHANCONG_RAP') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;


    -- Kiểm tra tài khoản phải là QUAN_LY_RAP
    IF NOT EXISTS (
        SELECT 1
        FROM dbo.NGUOIDUNG nd
        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID
        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro = 'QUAN_LY_RAP'
    )
    BEGIN
        ;THROW 50071, N'Tài khoản được phân công phải có vai trò QUAN_LY_RAP.', 1;
    END

    DECLARE @OwnTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    BEGIN TRY
    IF @OwnTran = 1 BEGIN TRANSACTION ELSE SAVE TRANSACTION AssignmentCreate;
    -- Serialize equivalent creates and updates; do not invent a period-overlap restriction.
    DECLARE @LockedRows BIGINT;
    SELECT @LockedRows = COUNT_BIG(*) FROM dbo.PHANCONG_RAP WITH (TABLOCKX, HOLDLOCK);
    IF @NgayKetThuc < @NgayBatDau THROW 50213, N'Khoảng thời gian phân công không hợp lệ.', 1;
    IF EXISTS (SELECT 1 FROM dbo.PHANCONG_RAP WHERE NguoiDungID = @NguoiDungID AND RapID = @RapID
        AND NgayBatDau = @NgayBatDau AND (NgayKetThuc = @NgayKetThuc OR (NgayKetThuc IS NULL AND @NgayKetThuc IS NULL))
        AND TrangThai = N'Hiệu lực') THROW 50401, N'Phân công hoàn toàn giống nhau đã tồn tại.', 1;
    INSERT INTO dbo.PHANCONG_RAP (NguoiDungID, RapID, NgayBatDau, NgayKetThuc, TrangThai)
    VALUES (@NguoiDungID, @RapID, @NgayBatDau, @NgayKetThuc, N'Hiệu lực');

    DECLARE @NewAssignmentID INT = SCOPE_IDENTITY();
    IF @OwnTran = 1 COMMIT TRANSACTION;

    SELECT
        pcr.PhanCongID,
        pcr.NguoiDungID,
        nd.HoTen,
        pcr.RapID,
        r.TenRap,
        pcr.NgayBatDau,
        pcr.NgayKetThuc,
        pcr.TrangThai
    FROM dbo.PHANCONG_RAP pcr
    INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID
    INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID
    WHERE pcr.PhanCongID = @NewAssignmentID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() = -1 ROLLBACK TRANSACTION;
        ELSE IF XACT_STATE() = 1
        BEGIN
            IF @OwnTran = 1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION AssignmentCreate;
        END
        ;THROW;
    END CATCH
END;

CREATE   PROCEDURE dbo.sp_Admin_Cinema_Create
(
    @ActorID INT,
    @TenRap NVARCHAR(150),
    @DiaChi NVARCHAR(255),
    @ThanhPho NVARCHAR(100),
    @SoDienThoai VARCHAR(20) = NULL,
    @MoTa NVARCHAR(500) = NULL,
    @NgayHoatDong DATE = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    -- R3B: current account, actor eligibility, then every required permission.
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N'Hoạt động')
        THROW 50300, N'Tài khoản không tồn tại hoặc đã bị khóa.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID
                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN ('ADMIN'))
        THROW 50301, N'Vai trò không được phép thực hiện thao tác này.', 1;
    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, 'QL_RAP') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;


    INSERT INTO dbo.RAPCHIEUPHIM (TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, NgayHoatDong, TrangThai)
    VALUES (@TenRap, @DiaChi, @ThanhPho, @SoDienThoai, @MoTa, @NgayHoatDong, N'Hoạt động');

    SELECT RapID, TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, NgayHoatDong, TrangThai
    FROM dbo.RAPCHIEUPHIM
    WHERE RapID = SCOPE_IDENTITY();
END;

CREATE   PROCEDURE dbo.sp_Admin_Cinema_Delete

    @ActorID INT,
    @RapID INT
AS
BEGIN
    SET NOCOUNT ON;
    -- R3B: current account, actor eligibility, then every required permission.
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N'Hoạt động')
        THROW 50300, N'Tài khoản không tồn tại hoặc đã bị khóa.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID
                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN ('ADMIN'))
        THROW 50301, N'Vai trò không được phép thực hiện thao tác này.', 1;
    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, 'QL_RAP') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;

    IF NOT EXISTS (SELECT 1 FROM dbo.RAPCHIEUPHIM WHERE RapID = @RapID)
        THROW 50095, N'Rạp không tồn tại.', 1;
    IF EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE RapID = @RapID)
       OR EXISTS (SELECT 1 FROM dbo.PHANCONG_RAP WHERE RapID = @RapID)
       OR EXISTS (SELECT 1 FROM dbo.BANGGIA WHERE RapID = @RapID)
       OR EXISTS (SELECT 1 FROM dbo.HINHANH_RAPCHIEUPHIM WHERE RapID = @RapID)
        THROW 50096, N'Rạp đã có dữ liệu phụ thuộc; hãy chuyển trạng thái sang Tạm đóng thay vì xóa.', 1;
    DELETE dbo.RAPCHIEUPHIM WHERE RapID = @RapID;
    SELECT N'Đã xóa rạp.' AS [Message];
END;

CREATE   PROCEDURE dbo.sp_Admin_Cinema_Update
(
    @ActorID INT,
    @RapID INT,
    @TenRap NVARCHAR(150),
    @DiaChi NVARCHAR(255),
    @ThanhPho NVARCHAR(100),
    @SoDienThoai VARCHAR(20),
    @MoTa NVARCHAR(500),
    @TrangThai NVARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;
    -- R3B: current account, actor eligibility, then every required permission.
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N'Hoạt động')
        THROW 50300, N'Tài khoản không tồn tại hoặc đã bị khóa.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID
                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN ('ADMIN'))
        THROW 50301, N'Vai trò không được phép thực hiện thao tác này.', 1;
    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, 'QL_RAP') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;


    UPDATE dbo.RAPCHIEUPHIM
    SET TenRap = @TenRap,
        DiaChi = @DiaChi,
        ThanhPho = @ThanhPho,
        SoDienThoai = @SoDienThoai,
        MoTa = @MoTa,
        TrangThai = @TrangThai
    WHERE RapID = @RapID;

    IF @@ROWCOUNT = 0 THROW 50095, N'Rạp không tồn tại.', 1;

    SELECT RapID, TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, TrangThai
    FROM dbo.RAPCHIEUPHIM
    WHERE RapID = @RapID;
END;

CREATE   PROCEDURE dbo.sp_Admin_Genre_Create
(
    @ActorID INT,
    @TenTheLoai NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;
    -- R3B: current account, actor eligibility, then every required permission.
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N'Hoạt động')
        THROW 50300, N'Tài khoản không tồn tại hoặc đã bị khóa.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID
                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN ('ADMIN'))
        THROW 50301, N'Vai trò không được phép thực hiện thao tác này.', 1;
    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, 'QL_THELOAI') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;

