    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, 'QL_NGUOIDUNG') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;


    UPDATE dbo.NGUOIDUNG
    SET TrangThai = @TrangThai
    WHERE NguoiDungID = @NguoiDungID;

    IF @@ROWCOUNT = 0 THROW 50403, N'Người dùng không tồn tại.', 1;

    SELECT NguoiDungID, HoTen, Email, TrangThai FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID;
END;

-- Baseline: procedures/auth/auth_procedures.sql:18 (dbo.sp_Auth_RegisterCustomer)
CREATE   PROCEDURE dbo.sp_Auth_RegisterCustomer
(
    @HoTen NVARCHAR(100),
    @Email VARCHAR(150),
    @MatKhauHash VARCHAR(255),
    @SoDienThoai VARCHAR(20) = NULL,
    @NgaySinh DATE = NULL,
    @GioiTinh NVARCHAR(10) = NULL,
    @NewUserId INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    IF @NgaySinh > dbo.fn_HomNay() THROW 50400, N'Ngày sinh không được ở tương lai.', 1;

    -- Transaction lồng nhau đúng kỹ thuật:
    --  * Gọi độc lập (@@TRANCOUNT = 0): thủ tục tự BEGIN/COMMIT/ROLLBACK.
    --  * Gọi trong transaction của bên gọi: dùng SAVE TRANSACTION, khi lỗi chỉ rollback phần của mình,
    --    không hủy transaction ngoài.
    DECLARE @TuMoTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;

    BEGIN TRY
        IF @TuMoTran = 1
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION sp_Auth_RegisterCustomer;

        -- 1. Kiểm tra email đã tồn tại chưa
        IF EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE Email = @Email)
        BEGIN
            ;THROW 50010, N'Email này đã được sử dụng trong hệ thống.', 1;
        END

        -- 2. Kiểm tra số điện thoại (nếu có)
        IF @SoDienThoai IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE SoDienThoai = @SoDienThoai)
        BEGIN
            ;THROW 50011, N'Số điện thoại này đã được sử dụng trong hệ thống.', 1;
        END

        -- 3. Lấy VaiTroID của vai trò KHACH_HANG
        DECLARE @VaiTroID INT;
        SELECT @VaiTroID = VaiTroID FROM dbo.VAITRO WHERE MaVaiTro = 'KHACH_HANG';

        IF @VaiTroID IS NULL
        BEGIN
            ;THROW 50012, N'Vai trò KHACH_HANG chưa được cấu hình.', 1;
        END

        -- 4. Thêm tài khoản mới vào NGUOIDUNG
        INSERT INTO dbo.NGUOIDUNG (VaiTroID, HoTen, Email, MatKhau, SoDienThoai, NgayTao, TrangThai)
        VALUES (@VaiTroID, @HoTen, @Email, @MatKhauHash, @SoDienThoai, dbo.fn_BayGio(), N'Hoạt động');

        SET @NewUserId = SCOPE_IDENTITY();

        -- 5. Tạo bản ghi HOSOKHACHHANG tương ứng
        INSERT INTO dbo.HOSOKHACHHANG (NguoiDungID, NgaySinh, GioiTinh, DiemTichLuy)
        VALUES (@NewUserId, @NgaySinh, @GioiTinh, 0);

        IF @TuMoTran = 1
            COMMIT TRANSACTION;

        -- Trả về thông tin tài khoản vừa tạo
        SELECT
            nd.NguoiDungID,
            nd.HoTen,
            nd.Email,
            nd.SoDienThoai,
            vt.MaVaiTro,
            vt.TenVaiTro,
            nd.TrangThai,
            hk.DiemTichLuy
        FROM dbo.NGUOIDUNG nd
        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID
        LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID
        WHERE nd.NguoiDungID = @NewUserId;

    END TRY
    BEGIN CATCH
        DECLARE @LoiSo INT = ERROR_NUMBER();
        DECLARE @LoiMsg NVARCHAR(2048) = ERROR_MESSAGE();

        SET @NewUserId = NULL;

        IF XACT_STATE() = -1
        BEGIN
            -- Transaction đã không thể commit: bắt buộc rollback toàn bộ
            ROLLBACK TRANSACTION;
        END
        ELSE IF XACT_STATE() = 1
        BEGIN
            IF @TuMoTran = 1
                ROLLBACK TRANSACTION;
            ELSE
                ROLLBACK TRANSACTION sp_Auth_RegisterCustomer;
        END

        -- Hai yêu cầu đăng ký đồng thời có thể cùng qua bước kiểm tra; UNIQUE là chốt chặn cuối cùng
        IF @LoiSo IN (2601, 2627) AND @LoiMsg LIKE N'%UQ_NGUOIDUNG_Email%'
        BEGIN
            ;THROW 50010, N'Email này đã được sử dụng trong hệ thống.', 1;
        END
        IF @LoiSo IN (2601, 2627) AND @LoiMsg LIKE N'%UQ_NGUOIDUNG_SoDienThoai%'
        BEGIN
            ;THROW 50011, N'Số điện thoại này đã được sử dụng trong hệ thống.', 1;
        END

        ;THROW;
    END CATCH
END;

-- Baseline: migrations/012_booking_limits_and_pricing.sql:253 (dbo.sp_Booking_Create)
CREATE   PROCEDURE dbo.sp_Booking_Create
(
    @NguoiDungID INT,
    @SuatChieuID INT,
    @MaKhuyenMai VARCHAR(50) = NULL,
    -- Danh sách ID ghế ngăn cách bởi dấu phẩy, ví dụ '101,102'
    @DanhSachGheId VARCHAR(MAX),
    -- Chuỗi JSON danh sách đồ ăn: '[{"SanPhamID":1,"SoLuong":2},{"SanPhamID":2,"SoLuong":1}]'
    @DanhSachDoAnJson NVARCHAR(MAX) = NULL,
    @NewDonDatVeID INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    -- R3B: current account, actor eligibility, then every required permission.
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N'Hoạt động')
        THROW 50300, N'Tài khoản không tồn tại hoặc đã bị khóa.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID
                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN ('KHACH_HANG'))
        THROW 50301, N'Vai trò không được phép thực hiện thao tác này.', 1;
    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, 'DAT_VE') = 0
        THROW 50302, N'Không có quyền thực hiện thao tác này.', 1;


    -- Gọi được cả độc lập lẫn trong transaction của bên gọi: chỉ COMMIT/ROLLBACK khi tự mở transaction,
    -- ngược lại dùng SAVE TRANSACTION và chỉ rollback phần của mình.
    DECLARE @TuMoTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;

    BEGIN TRY
        -- Preserve own transaction/savepoint and existing seat-conflict coordination.
        IF @TuMoTran = 1
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION sp_Booking_Create;

        -- 1. Kiểm tra tài khoản khách hàng hợp lệ. Khóa dòng khách (UPDLOCK, HOLDLOCK, gán vào biến, không phát
        -- result set) TRƯỚC khóa suất chiếu: các đơn song song của cùng một khách bị xếp hàng, nên giới hạn số đơn
        -- đang giữ chỗ bên dưới không thể bị vượt bằng race. R2.1 thêm parent trước suất/ghế.
        DECLARE @KhoaKhach INT;
        SELECT @KhoaKhach = NguoiDungID
        FROM dbo.NGUOIDUNG WITH (UPDLOCK, HOLDLOCK)
        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N'Hoạt động';

        IF @KhoaKhach IS NULL
        BEGIN
            ;THROW 50020, N'Tài khoản người dùng không tồn tại hoặc đã bị khóa.', 1;
        END

        -- 1b. Tối đa fn_GioiHanDonDangGiu() đơn đang giữ chỗ (chưa thanh toán và chưa quá HanGiuCho) mỗi khách
        IF (SELECT COUNT(*) FROM dbo.DONDATVE
            WHERE NguoiDungID = @NguoiDungID AND TrangThai = N'Chờ thanh toán' AND HanGiuCho > dbo.fn_BayGio())
           >= dbo.fn_GioiHanDonDangGiu()
        BEGIN
            ;THROW 50028, N'Bạn đang giữ chỗ tối đa số đơn cho phép. Hãy thanh toán hoặc chờ đơn cũ hết hạn.', 1;
        END

        -- R2.1 discovery is an RCSI read, without retained child locks. Never invert R1 room -> show.
        DECLARE @PhongID INT, @PhimID INT, @RapID INT, @LockedID INT;
        SELECT @PhongID = s.PhongID, @PhimID = s.PhimID, @RapID = p.RapID
        FROM dbo.SUATCHIEU s JOIN dbo.PHONGCHIEU p ON p.PhongID = s.PhongID
        WHERE s.SuatChieuID = @SuatChieuID;
        IF @PhongID IS NULL
            THROW 50021, N'Suất chiếu không tồn tại.', 1;

        -- Shared parent locks retain current movie dates/status and cinema status until commit.
        -- Existing parent UPDATE statements need X locks and therefore coordinate without rewrites.
        SELECT @LockedID = PhimID FROM dbo.PHIM WITH (HOLDLOCK) WHERE PhimID = @PhimID;
        SET @LockedID = NULL;
        SELECT @LockedID = RapID FROM dbo.RAPCHIEUPHIM WITH (HOLDLOCK) WHERE RapID = @RapID;
        SET @LockedID = NULL;
        SELECT @LockedID = PhongID FROM dbo.PHONGCHIEU WITH (UPDLOCK, HOLDLOCK)
        WHERE PhongID = @PhongID AND RapID = @RapID;
        IF @LockedID IS NULL
            THROW 50022, N'Suất chiếu không còn đủ điều kiện đặt vé.', 1;
        SET @LockedID = NULL;
        SELECT @LockedID = SuatChieuID FROM dbo.SUATCHIEU WITH (UPDLOCK, HOLDLOCK)
        WHERE SuatChieuID = @SuatChieuID AND PhongID = @PhongID AND PhimID = @PhimID;
        -- A concurrent edit may change the discovered movie. Reject and reload instead of locking
        -- a different movie after the child, which would violate the parent-first protocol.
        IF @LockedID IS NULL OR NOT EXISTS (
            SELECT 1 FROM dbo.vw_LichChieuChiTiet
            WHERE SuatChieuID = @SuatChieuID AND IsBookable = 1
        )
            THROW 50022, N'Suất chiếu không còn đủ điều kiện đặt vé.', 1;

        -- 2b. Giải phóng các đơn đã quá hạn giữ ghế của suất chiếu này (đã khóa suất chiếu ở trên)
        EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatChieuID, @TraVeKetQua = 0;

        -- 3. Tách danh sách ghế cần đặt vào bảng tạm
        DECLARE @BangGheCanDat TABLE (GheID INT PRIMARY KEY);
        INSERT INTO @BangGheCanDat (GheID)
        SELECT DISTINCT CAST(value AS INT)
        FROM STRING_SPLIT(@DanhSachGheId, ',')
        WHERE LTRIM(RTRIM(value)) <> '';

        IF NOT EXISTS (SELECT 1 FROM @BangGheCanDat)
        BEGIN
            ;THROW 50023, N'Vui lòng chọn ít nhất một ghế để đặt vé.', 1;
        END

        IF (SELECT COUNT(*) FROM @BangGheCanDat) > dbo.fn_GioiHanGheMoiDon()
        BEGIN
            ;THROW 50026, N'Mỗi đơn chỉ được đặt tối đa số ghế cho phép.', 1;
        END

        -- 4. KHÓA CÁC GHẾ VÀ KIỂM TRA TOÀN VẸN:
        -- Khóa hàng trong GHE để ngăn chặn xung đột giữa các giao dịch đồng thời
        DECLARE @GheCount INT;
        SELECT @GheCount = COUNT(*)
        FROM dbo.GHE g WITH (UPDLOCK, HOLDLOCK)
        INNER JOIN @BangGheCanDat bg ON g.GheID = bg.GheID
        WHERE g.PhongID = @PhongID AND g.TrangThai = N'Hoạt động';

        IF @GheCount <> (SELECT COUNT(*) FROM @BangGheCanDat)
        BEGIN
            ;THROW 50024, N'Một số ghế được chọn không hợp lệ, không thuộc phòng chiếu này hoặc đang bảo trì.', 1;
        END

        -- 5. KIỂM TRA TRÙNG GHẾ: Đảm bảo không có ghế nào trong danh sách đã được đặt trong đơn hợp lệ
        IF EXISTS (
            SELECT 1
            FROM dbo.CHITIETVE cv WITH (UPDLOCK, HOLDLOCK)
            INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID
            INNER JOIN @BangGheCanDat bg ON cv.GheID = bg.GheID
            WHERE ddv.SuatChieuID = @SuatChieuID
              AND cv.TrangThai <> N'Đã hủy'
              AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1
        )
        BEGIN
            ;THROW 50025, N'Một hoặc nhiều ghế bạn chọn vừa được khách hàng khác đặt. Vui lòng chọn ghế khác.', 1;
        END

        -- 6. TÍNH SNAPSHOT GIÁ VÉ CHO TỪNG GHẾ (dùng hàm fn_TinhGiaVe)
        DECLARE @BangChiTietVe TABLE (
            GheID INT,
            GiaVe DECIMAL(18,2),
            MaVe VARCHAR(100)
        );

        INSERT INTO @BangChiTietVe (GheID, GiaVe, MaVe)
        SELECT
            bg.GheID,
            dbo.fn_TinhGiaVe(@SuatChieuID, bg.GheID),
            CONCAT('TK-', FORMAT(dbo.fn_BayGio(), 'yyyyMMddHHmmss'), '-', CAST(bg.GheID AS VARCHAR(10)), '-', LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 6))
        FROM @BangGheCanDat bg;

        DECLARE @TongTienVe DECIMAL(18,2) = 0;
        SELECT @TongTienVe = ISNULL(SUM(GiaVe), 0) FROM @BangChiTietVe;

        -- 7. TÍNH SNAPSHOT ĐỒ ĂN (NẾU CÓ TRUYỀN JSON)
        DECLARE @BangChiTietDoAn TABLE (
            SanPhamID INT,
            SoLuong INT,
            DonGia DECIMAL(18,2)
        );

        IF @DanhSachDoAnJson IS NOT NULL
        BEGIN
            IF ISJSON(@DanhSachDoAnJson) <> 1 OR LEFT(LTRIM(@DanhSachDoAnJson), 1) <> '['
                THROW 50402, N'Danh sách sản phẩm phải là mảng JSON hợp lệ.', 1;
            IF EXISTS (SELECT 1 FROM OPENJSON(@DanhSachDoAnJson) WHERE [type] <> 5)
                THROW 50402, N'Mỗi sản phẩm phải là một object hợp lệ.', 1;
            IF EXISTS (
                SELECT 1 FROM OPENJSON(@DanhSachDoAnJson) item
                OUTER APPLY (SELECT [value], [type] FROM OPENJSON(item.value) WHERE [key]='SanPhamID') product
                OUTER APPLY (SELECT [value], [type] FROM OPENJSON(item.value) WHERE [key]='SoLuong') quantity
                WHERE product.[type] IS NULL OR product.[type] <> 2 OR quantity.[type] IS NULL OR quantity.[type] <> 2
                  OR product.value LIKE '%[^0-9]%' OR quantity.value LIKE '%[^0-9]%'
                  OR TRY_CONVERT(INT, product.value) IS NULL OR TRY_CONVERT(INT, product.value) <= 0
                  OR TRY_CONVERT(BIGINT, quantity.value) IS NULL OR TRY_CONVERT(BIGINT, quantity.value) <= 0
                  OR (SELECT COUNT(*) FROM OPENJSON(item.value) WHERE [key]='SanPhamID') <> 1
                  OR (SELECT COUNT(*) FROM OPENJSON(item.value) WHERE [key]='SoLuong') <> 1
            ) THROW 50402, N'Mọi mã sản phẩm và số lượng phải là số nguyên hợp lệ.', 1;

            DECLARE @ProductInput TABLE (SanPhamID INT NOT NULL, SoLuong BIGINT NOT NULL);
            INSERT @ProductInput(SanPhamID,SoLuong)
            SELECT CONVERT(INT,product.value),CONVERT(BIGINT,quantity.value)
            FROM OPENJSON(@DanhSachDoAnJson) item
            CROSS APPLY (SELECT [value] FROM OPENJSON(item.value) WHERE [key]='SanPhamID') product
            CROSS APPLY (SELECT [value] FROM OPENJSON(item.value) WHERE [key]='SoLuong') quantity;
            -- Cộng dồn các dòng trùng sản phẩm TRƯỚC khi kiểm trần (không lách được bằng cách tách dòng).
            -- SoLuong đọc BIGINT để giá trị ngoài miền INT bị chặn bởi trần thay vì gây lỗi tràn số.
            IF EXISTS (
                SELECT 1
                FROM @ProductInput j
                GROUP BY j.SanPhamID
                HAVING SUM(j.SoLuong) > dbo.fn_GioiHanSoLuongSanPham()
            )
            BEGIN
                ;THROW 50027, N'Số lượng mỗi sản phẩm vượt quá mức cho phép.', 1;
            END

            DECLARE @ValidProducts INT;
            SELECT @ValidProducts = COUNT(*) FROM dbo.SANPHAM sp WITH (UPDLOCK, HOLDLOCK)
            INNER JOIN (SELECT DISTINCT SanPhamID FROM @ProductInput) requested ON requested.SanPhamID=sp.SanPhamID
            WHERE sp.TrangThai=N'Đang bán';
            IF @ValidProducts <> (SELECT COUNT(DISTINCT SanPhamID) FROM @ProductInput)
                THROW 50402, N'Một hoặc nhiều sản phẩm không tồn tại hoặc không đang bán.', 1;

            INSERT INTO @BangChiTietDoAn (SanPhamID, SoLuong, DonGia)
            SELECT
                j.SanPhamID,
                CAST(SUM(j.SoLuong) AS INT),
                sp.Gia
            FROM @ProductInput j
            INNER JOIN dbo.SANPHAM sp WITH (UPDLOCK, HOLDLOCK) ON j.SanPhamID = sp.SanPhamID
            WHERE j.SoLuong > 0 AND sp.TrangThai = N'Đang bán'
            GROUP BY j.SanPhamID, sp.Gia;
        END

        DECLARE @TongTienDoAn DECIMAL(18,2) = 0;
        SELECT @TongTienDoAn = ISNULL(SUM(SoLuong * DonGia), 0) FROM @BangChiTietDoAn;

        -- Re-check DB time immediately before the first booking write (promotion usage/order).
        -- Resource/seat locks above remain held; a parent cannot change between check and commit.
        IF NOT EXISTS (SELECT 1 FROM dbo.vw_LichChieuChiTiet WHERE SuatChieuID = @SuatChieuID AND IsBookable = 1)
            THROW 50022, N'Suất chiếu không còn đủ điều kiện đặt vé.', 1;

        -- 8. TÍNH KHUYẾN MÃI (NẾU CÓ)
        DECLARE @KhuyenMaiID INT = NULL;
        DECLARE @TienGiamGia DECIMAL(18,2) = 0;
        DECLARE @TongTruocGiam DECIMAL(18,2) = @TongTienVe + @TongTienDoAn;

        IF @MaKhuyenMai IS NOT NULL AND LTRIM(RTRIM(@MaKhuyenMai)) <> ''
        BEGIN
            DECLARE @LockedPromotionUsage INT;
            -- R2.2: promotion follows booking resources/products in the lock hierarchy.
            -- Lock BEFORE validation; the current state and final quota stay protected
            -- until the owning transaction commits/rolls back (also for caller transactions).
            -- Read a non-covered column as well as the ID: the unique code index
            -- alone does not protect status/quota updates on the clustered row.
            SELECT @KhuyenMaiID = KhuyenMaiID, @LockedPromotionUsage = SoLuongDaDung
            FROM dbo.KHUYENMAI WITH (UPDLOCK, HOLDLOCK, INDEX(UQ_KHUYENMAI_MaCode))
            WHERE MaCode = @MaKhuyenMai;
            IF @KhuyenMaiID IS NULL OR @LockedPromotionUsage < 0
                THROW 50029, N'Khuyến mãi yêu cầu không còn khả dụng. Vui lòng kiểm tra lại đơn.', 1;

            DECLARE @LoaiGiamGia NVARCHAR(20);
            DECLARE @GiaTriGiam DECIMAL(18,2);
            DECLARE @IsValid BIT;
            DECLARE @Msg NVARCHAR(255);

            EXEC dbo.sp_Promotion_Validate
                @NguoiDungID = @NguoiDungID,
                @MaCode = @MaKhuyenMai,
                @TongTienDon = @TongTruocGiam,
                @KhuyenMaiID = @KhuyenMaiID OUTPUT,
                @LoaiGiamGia = @LoaiGiamGia OUTPUT,
                @GiaTriGiam = @GiaTriGiam OUTPUT,
                @TienGiam = @TienGiamGia OUTPUT,
                @IsValid = @IsValid OUTPUT,
                @Message = @Msg OUTPUT;

            IF ISNULL(@IsValid, 0) <> 1 OR @KhuyenMaiID IS NULL
                THROW 50029, N'Khuyến mãi yêu cầu không còn khả dụng. Vui lòng kiểm tra lại đơn.', 1;

            -- Chặn cứng lần nữa: giảm tối đa 99% tổng tạm tính, tổng đơn luôn > 0
            DECLARE @TranGiam DECIMAL(18,2) = ROUND(@TongTruocGiam * dbo.fn_GioiHanGiamGiaPhanTram() / 100.0, 2, 1);
            IF @TienGiamGia > @TranGiam SET @TienGiamGia = @TranGiam;

            -- Validation and consumption use the same protected row/transaction.
            UPDATE dbo.KHUYENMAI
            SET SoLuongDaDung = SoLuongDaDung + 1
            WHERE KhuyenMaiID = @KhuyenMaiID AND SoLuongDaDung < SoLuong;
            IF @@ROWCOUNT <> 1
                THROW 50029, N'Khuyến mãi yêu cầu không còn khả dụng. Vui lòng kiểm tra lại đơn.', 1;
        END

        -- Promotion acquisition can wait. Keep R2.1's final DB-time check current
        -- before order writes; rejection also rolls back any promotion consumption.
        IF NOT EXISTS (SELECT 1 FROM dbo.vw_LichChieuChiTiet WHERE SuatChieuID = @SuatChieuID AND IsBookable = 1)
            THROW 50022, N'Suất chiếu không còn đủ điều kiện đặt vé.', 1;

        -- 9. TẠO BẢN GHI DONDATVE
        INSERT INTO dbo.DONDATVE
        (
            NguoiDungID,
            SuatChieuID,
            KhuyenMaiID,
            NgayDat,
            TongTienVe,
            TongTienDoAn,
            TienGiamGia,
            TrangThai,
            HanGiuCho
        )
        VALUES
        (
            @NguoiDungID,
            @SuatChieuID,
            @KhuyenMaiID,
            dbo.fn_BayGio(),
            @TongTienVe,
            @TongTienDoAn,
            @TienGiamGia,
            N'Chờ thanh toán',
            DATEADD(MINUTE, dbo.fn_ThoiGianGiuChoPhut(), dbo.fn_BayGio())
        );

        SET @NewDonDatVeID = SCOPE_IDENTITY();

        -- 10. TẠO CÁC BẢN GHI CHITIETVE
        INSERT INTO dbo.CHITIETVE (DonDatVeID, GheID, GiaVe, MaVe, TrangThai)
        SELECT
            @NewDonDatVeID,
            GheID,
            GiaVe,
            MaVe,
            N'Đã đặt'
        FROM @BangChiTietVe;

        -- 11. TẠO CÁC BẢN GHI CHITIETDOAN (NẾU CÓ)
        IF EXISTS (SELECT 1 FROM @BangChiTietDoAn)
        BEGIN
            INSERT INTO dbo.CHITIETDOAN (DonDatVeID, SanPhamID, SoLuong, DonGia)
            SELECT
                @NewDonDatVeID,
                SanPhamID,
                SoLuong,
                DonGia
            FROM @BangChiTietDoAn;
        END

        IF @TuMoTran = 1
            COMMIT TRANSACTION;

        -- Trả về kết quả chốt của đơn đặt vé
        SELECT
            ddv.DonDatVeID,
            ddv.NguoiDungID,
            ddv.SuatChieuID,
            ddv.NgayDat,
            ddv.TongTienVe,
            ddv.TongTienDoAn,
            ddv.TienGiamGia,
            (ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia) AS TongThanhToan,
            ddv.TrangThai,
            ddv.HanGiuCho,
            (SELECT COUNT(*) FROM dbo.CHITIETVE WHERE DonDatVeID = ddv.DonDatVeID) AS SoLuongVe
        FROM dbo.DONDATVE ddv
        WHERE ddv.DonDatVeID = @NewDonDatVeID;

    END TRY
    BEGIN CATCH
        IF XACT_STATE() = -1
            ROLLBACK TRANSACTION;
        ELSE IF XACT_STATE() = 1
        BEGIN
            IF @TuMoTran = 1
                ROLLBACK TRANSACTION;
            ELSE
                ROLLBACK TRANSACTION sp_Booking_Create;
        END
        ;THROW;
    END CATCH
END;

