        -- continue to apply the R2.1 IsBookable filter in sp_Showtime_GetDetail.
        SELECT SuatChieuID,PhimID,TenPhim,PosterURL,ThoiLuong,DoTuoi,RapID,TenRap,
            DiaChiRap,ThanhPho,PhongID,TenPhong,LoaiPhong,ThoiGianBatDau,ThoiGianKetThuc,
            NgayChieu,GioBatDau,GioKetThuc,DinhDang,GiaVeCoBan,TrangThaiSuatChieu,
            TongSoGhe,SoGheDaDat,(TongSoGhe-SoGheDaDat) AS SoGheConLai
        FROM dbo.vw_LichChieuChiTiet WHERE SuatChieuID=@SuatChieuID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;
        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION ManagerShowtimeUpdate; END
        SET XACT_ABORT OFF;
        ;THROW;
    END CATCH
END;

CREATE   PROCEDURE dbo.sp_Order_Cancel
(
    @NguoiDungID INT,
    @DonDatVeID INT
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @TrangThai NVARCHAR(50);
        DECLARE @KhuyenMaiID INT;

        SELECT
            @TrangThai = TrangThai,
            @KhuyenMaiID = KhuyenMaiID
        FROM dbo.DONDATVE WITH (UPDLOCK, HOLDLOCK)
        WHERE DonDatVeID = @DonDatVeID AND NguoiDungID = @NguoiDungID;

        IF @TrangThai IS NULL
        BEGIN
            ;THROW 50034, N'Đơn đặt vé không tồn tại hoặc bạn không có quyền thao tác.', 1;
        END

        IF @TrangThai <> N'Chờ thanh toán'
        BEGIN
            ;THROW 50035, N'Chỉ có thể hủy đơn khi đang ở trạng thái Chờ thanh toán.', 1;
        END

        -- Cập nhật đơn thành Đã hủy
        UPDATE dbo.DONDATVE
        SET TrangThai = N'Đã hủy'
        WHERE DonDatVeID = @DonDatVeID;

        -- Cập nhật vé thành Đã hủy để giải phóng ghế
        UPDATE dbo.CHITIETVE
        SET TrangThai = N'Đã hủy'
        WHERE DonDatVeID = @DonDatVeID;

        -- Hoàn lại lượt dùng mã khuyến mãi nếu có
        IF @KhuyenMaiID IS NOT NULL
        BEGIN
            UPDATE dbo.KHUYENMAI
            SET SoLuongDaDung = CASE WHEN SoLuongDaDung > 0 THEN SoLuongDaDung - 1 ELSE 0 END
            WHERE KhuyenMaiID = @KhuyenMaiID;
        END

        COMMIT TRANSACTION;

        SELECT N'Hủy đơn đặt vé thành công.' AS [Message];

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        ;THROW;
    END CATCH
END;

-- Baseline: procedures/system/system_procedures.sql:38 (dbo.sp_Order_ExpirePending)
CREATE   PROCEDURE dbo.sp_Order_ExpirePending
(
    @SuatChieuID INT = NULL,
    @TraVeKetQua BIT = 1   -- 0 khi gọi lồng trong thủ tục khác (không trả recordset)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TuMoTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    DECLARE @Het TABLE (DonDatVeID INT PRIMARY KEY, KhuyenMaiID INT NULL);
    DECLARE @SoDon INT = 0;

